const data = $json;

// Map GLPI computer type to Workbench device type
let deviceType = "LAPTOP";
const typeName = (data.computer_type || "").toLowerCase();
if (typeName.includes("desktop")) deviceType = "DESKTOP";
else if (typeName.includes("all in one")) deviceType = "ALL_IN_ONE";
else if (typeName.includes("tablet")) deviceType = "TABLET";

// Parse memory
let memoryGb = null;
const memMatch = data.memory_name ? data.memory_name.match(/([\d.]+)/) : null;
if (memMatch) memoryGb = Math.round(parseFloat(memMatch[1]));

// Parse storage
let storageSizeGb = null;
let storageType = "UNKNOWN";
const s = data.storage_name || "";

const gbMatch = s.match(/(\d+)\s*GB/i);
const tbMatch = s.match(/(\d+)\s*TB/i);
if (gbMatch) storageSizeGb = parseInt(gbMatch[1]);
else if (tbMatch) storageSizeGb = parseInt(tbMatch[1]) * 1024;
else {
  const modelSizeMatch = s.match(/(\d{3,4})(?:GB|MEE|G)/i);
  if (modelSizeMatch) storageSizeGb = parseInt(modelSizeMatch[1]);
}

if (s.includes("NVMe") || s.includes("SSD") || s.includes("UMIS") || s.includes("HFM")) storageType = "SSD";
else if (s.includes("HDD")) storageType = "HDD";
else if (s.includes("eMMC")) storageType = "EMMC";

return {
  inventory_number: data.inventory_number,
  serial_number: data.serial_number,
  device_type: deviceType,
  device_specification_data: {
    manufacturer: data.manufacturer_name || "",
    model_name: data.model_name || "",
    processor: data.processor_name || "",
    memory_gb: memoryGb,
    storage_type: storageType,
    storage_size_gb: storageSizeGb,
    source: "FOG"
  },
  stage_code: "RECEIVED",
  wipe_status: "PENDING",
  notes: data.comment || ""
};
